    private ImageView logo(boolean mark){ImageView view=new ImageView(this);int w=mark?105:194,h=mark?72:37;float scale=getResources().getDisplayMetrics().density*2;android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(Math.round(w*scale),Math.round(h*scale),android.graphics.Bitmap.Config.ARGB_8888);android.graphics.Canvas canvas=new android.graphics.Canvas(bitmap);canvas.scale(scale,scale);android.graphics.Paint paint=new android.graphics.Paint(android.graphics.Paint.ANTI_ALIAS_FLAG);paint.setColor(INK);if(mark){canvas.drawPath(BrandPaths.mark0(),paint);canvas.drawPath(BrandPaths.mark1(),paint);}else canvas.drawPath(BrandPaths.wordmark(),paint);view.setImageBitmap(bitmap);view.setContentDescription("VAutomate");view.setScaleType(ImageView.ScaleType.FIT_CENTER);return view;}
