        EditText remote=field(page,"Away · remote server (optional)","https://your-home.example",editing==null?"":editing.remote);
        local.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);remote.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);
        TextView hint=text("Both addresses must belong to this same home. Your phone's private remote connection must already be active when away.",11,MUTED);page.addView(hint);TextView error=text("",12,Color.rgb(213,159,136));error.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);addSpace(page,10);page.addView(error);
        addButton(page,editing==null?"Connect my home":"Save connection",true,()->{try{String title=name.getText().toString().trim();if(title.isEmpty())throw new IllegalArgumentException("Give your home a name.");if(title.length()>60)throw new IllegalArgumentException("Use a shorter home name.");String localOrigin=EndpointPolicy.normalize(local.getText().toString()),remoteOrigin=EndpointPolicy.normalize(remote.getText().toString());if(localOrigin.isEmpty()&&remoteOrigin.isEmpty())throw new IllegalArgumentException("Add at least one server address.");HomeStore.Home next=editing==null?homes.create(title,localOrigin,remoteOrigin):new HomeStore.Home(editing.id,title,localOrigin,remoteOrigin);if(editing!=null&&(!editing.local.equals(next.local)||!editing.remote.equals(next.remote))){vaultJobs.execute(()->{vault.clear(editing.id);});}homes.save(next);home=next;origin="";destroyWeb();hideKeyboard(name);note("Home connection saved");connect(null,false);}catch(Exception e){error.setText(e.getMessage());}});
        if(editing!=null||!homes.all().isEmpty())addButton(page,"Go back",false,()->{home=homes.selected();if(home!=null)connect(null,false);else showHomeForm(null);});addSpace(page,25);page.addView(text("SMART LIVING. SIMPLIFIED.",9,MUTED));
