    private void hideKeyboard(View view){((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(view.getWindowToken(),0);}
    private void buildShell(){root.removeAllViews();shell=column();root.addView(shell,new FrameLayout.LayoutParams(-1,-1));connectionStatus=text("",10,MUTED);stage=new FrameLayout(this);shell.addView(stage,new LinearLayout.LayoutParams(-1,0,1));if(web!=null){if(web.getParent()instanceof android.view.ViewGroup)((android.view.ViewGroup)web.getParent()).removeView(web);stage.addView(web,new FrameLayout.LayoutParams(-1,-1));}}
    private void showWelcomeIntro(){final FrameLayout overlay=new FrameLayout(this);overlay.setBackgroundColor(BG);overlay.setClickable(true);BrandArrivalView brand=new BrandArrivalView(this,"Your home. Entirely yours.");overlay.addView(brand,new FrameLayout.LayoutParams(-1,-1));root.addView(overlay,new FrameLayout.LayoutParams(-1,-1));brand.whenComplete(()->{if(ValueAnimatorEnabled())overlay.animate().alpha(0).setDuration(550).withEndAction(()->root.removeView(overlay)).start();else root.removeView(overlay);});}
    private void showLoading(String title,String subtitle){
        if(shell==null||shell.getParent()!=root)buildShell();if(loading!=null&&loading.getParent()==stage)stage.removeView(loading);
        arrivalDismissing=false;loading=new FrameLayout(this);final FrameLayout overlay=loading;loading.setBackgroundColor(BG);loading.setClickable(true);
        arrivalView=new BrandArrivalView(this,subtitle);loading.addView(arrivalView,new FrameLayout.LayoutParams(-1,-1));
        Button settings=button("Connection settings",false,()->showAppMenu());FrameLayout.LayoutParams bottom=new FrameLayout.LayoutParams(-2,dp(44),Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);bottom.bottomMargin=dp(34);settings.setVisibility(View.GONE);loading.addView(settings,bottom);main.postDelayed(()->{if(loading==overlay&&overlay.getParent()==stage)settings.setVisibility(View.VISIBLE);},5000);
        stage.addView(loading,new FrameLayout.LayoutParams(-1,-1));
    }
    private boolean ValueAnimatorEnabled(){return android.animation.ValueAnimator.areAnimatorsEnabled();}
    private void dismissLoading(){if(loading==null||arrivalDismissing)return;arrivalDismissing=true;FrameLayout overlay=loading;Runnable reveal=()->{if(loading!=overlay)return;loading=null;arrivalView=null;arrivalDismissing=false;if(ValueAnimatorEnabled())overlay.animate().alpha(0).setDuration(550).setInterpolator(new android.view.animation.PathInterpolator(.22f,1f,.36f,1f)).withEndAction(()->{if(overlay.getParent()==stage)stage.removeView(overlay);}).start();else if(overlay.getParent()==stage)stage.removeView(overlay);firstLaunch=false;};if(arrivalView!=null)arrivalView.whenComplete(reveal);else main.post(reveal);}
    private void errorScreen(String detail){arrivalView=null;connecting=false;ready=false;if(deadline!=null)main.removeCallbacks(deadline);if(shell==null||shell.getParent()!=root)buildShell();if(loading!=null&&loading.getParent()==stage)stage.removeView(loading);loading=new FrameLayout(this);loading.setBackgroundColor(BG);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);LinearLayout content=column();content.setGravity(Gravity.CENTER_VERTICAL);content.setPadding(dp(30),dp(40),dp(30),dp(40));scroll.addView(content);loading.addView(scroll);content.addView(logo(true),new LinearLayout.LayoutParams(dp(66),dp(49)));addSpace(content,27);content.addView(headline("Home is a little out of reach."));addSpace(content,14);content.addView(text(detail==null||detail.isEmpty()?"Check Wi-Fi or your private remote connection, then try again. Your saved home and sign-in are kept.":detail+"\n\nYour saved home and sign-in are kept.",13,MUTED));addButton(content,"Try again",true,()->connect(null,false));addButton(content,"Connection settings",false,()->showAppMenu());stage.addView(loading,new FrameLayout.LayoutParams(-1,-1));if(connectionStatus!=null)connectionStatus.setText(home.name+" · Offline");note("Home connection unavailable");scheduleRecovery();}
    private void scheduleRecovery(){if(recoveryCheck!=null)main.removeCallbacks(recoveryCheck);int ticket=generation;HomeStore.Home target=home;recoveryCheck=()->{if(!resumed||target==null||connecting||ready||ticket!=generation||shell==null||shell.getParent()!=root)return;tasks.execute(()->{ConnectionResolver.Result result=resolver.resolve(target,null);main.post(()->{if(!resumed||ticket!=generation||connecting||ready)return;if(result.success)connect(result.origin,true);else scheduleRecovery();});});};main.postDelayed(recoveryCheck,12000);}
    private void connect(String forced,boolean recovery){if(recoveryCheck!=null)main.removeCallbacks(recoveryCheck);if(home==null){showHomeForm(null);return;}if(connecting)return;connecting=true;int ticket=++generation;HomeStore.Home target=home;showLoading(recovery?"Finding your home.":"Welcome home.","Connecting to "+target.name+"…");note("Checking home connection");tasks.execute(()->{ConnectionResolver.Result result=resolver.resolve(target,forced);main.post(()->{if(ticket!=generation||isFinishing())return;connecting=false;if(!result.success){errorScreen(result.detail);return;}candidateOrigin=result.origin;useBundledDashboard=true;loadDashboard(result.origin,ticket);});});}
    private void loadDashboard(String chosen,int ticket){hideCameraFullscreen();origin=chosen;candidateOrigin=chosen;bridgeNonce=UUID.randomUUID().toString();ready=false;closePort();if(web==null)createWeb();else{web.stopLoading();web.clearHistory();}connectionStatus.setText(home.name+" · "+home.label(origin));note("Opening "+home.label(origin).toLowerCase(Locale.ROOT)+" connection");long revision=System.currentTimeMillis();String dashboardUrl=origin+EndpointPolicy.DASHBOARD+"?native=android&app=0.4.0-alpha.13&profile="+home.id+"&v="+revision+getPreferences(MODE_PRIVATE).getString("last-route:"+home.id,"#/overview");if(useBundledDashboard){try{if(bundledAssets==null)throw new IOException("Built-in interface missing");String bundledHtml=bundledAssets.entry().replace("<head>","<head><script>window.__VA_HOME_PROFILE__="+JSONObject.quote(home.id)+";</script>");web.loadDataWithBaseURL(dashboardUrl,bundledHtml,"text/html","UTF-8",dashboardUrl);}catch(IOException error){errorScreen("The built-in VAutomate interface could not load. Install the current app update and try again.");return;}}else web.loadUrl(dashboardUrl);deadline=()->{if(ticket==generation&&!ready)errorScreen("The dashboard did not finish opening. Check the server connection or update Android System WebView, then retry.");};main.postDelayed(deadline,20000);}
    private void createWeb(){web=new WebView(this);web.setBackgroundColor(BG);web.setOverScrollMode(View.OVER_SCROLL_NEVER);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(true);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setMediaPlaybackRequiresUserGesture(true);settings.setJavaScriptCanOpenWindowsAutomatically(false);settings.setSupportMultipleWindows(true);settings.setUserAgentString(settings.getUserAgentString()+" VAutomateAndroid/0.4.0-alpha.13");WebView.setWebContentsDebuggingEnabled(false);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.setDownloadListener((url,agent,disposition,mime,length)->handleDownload(url,disposition,mime));
        web.setWebViewClient(new WebViewClient(){
            @Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){if(request.isForMainFrame()&&EndpointPolicy.dashboard(request.getUrl().toString(),origin))return false;message("VAutomate stays inside its customer interface.");return true;}
            @Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){String url=request.getUrl().toString();if(!StudioReadOnlyPolicy.allows(url,request.getMethod(),origin))return new WebResourceResponse("text/plain","UTF-8",403,"Studio Read Only",Collections.emptyMap(),new ByteArrayInputStream("Disabled in Studio Preview".getBytes(java.nio.charset.StandardCharsets.UTF_8)));if(bundledAssets!=null&&EndpointPolicy.sameOrigin(url,origin)){WebResourceResponse asset=bundledAssets.response(request.getUrl());if(asset!=null)return asset;}return null;}
            @Override public void onPageStarted(WebView view,String url,android.graphics.Bitmap icon){closePort();if(!EndpointPolicy.dashboard(url,origin)){view.stopLoading();errorScreen("This address did not open the VAutomate dashboard.");}}
            @Override public void onPageFinished(WebView view,String url){if(EndpointPolicy.dashboard(url,origin))initializePage();}
            @Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame()&&EndpointPolicy.dashboard(request.getUrl().toString(),origin)&&shell!=null&&shell.getParent()==root){note("Dashboard loading failed");if(!ready)errorScreen("The dashboard could not load. Check your home connection and try again.");else checkCurrentConnection();}}
            @Override public void onReceivedHttpError(WebView view,WebResourceRequest request,WebResourceResponse response){if(request.isForMainFrame()&&EndpointPolicy.dashboard(request.getUrl().toString(),origin)&&shell!=null&&shell.getParent()==root)errorScreen("The dashboard returned HTTP "+response.getStatusCode()+". Check that VAutomate is installed on this server.");}
            @Override public void onReceivedSslError(WebView view,SslErrorHandler handler,SslError error){handler.cancel();note("HTTPS verification failed");errorScreen("The server's HTTPS certificate could not be verified. Correct the certificate or use your configured private HTTP address.");}
            @Override public boolean onRenderProcessGone(WebView view,RenderProcessGoneDetail detail){note("Dashboard renderer restarted");destroyWeb();errorScreen("Android stopped the dashboard. Your home and saved sign-in are kept. Tap Try again to reopen it.");return true;}
        });
        web.setWebChromeClient(new WebChromeClient(){
            @Override public void onShowCustomView(View view,CustomViewCallback callback){if(!trustedPage()||cameraFullscreen!=null){callback.onCustomViewHidden();return;}cameraFullscreenCallback=callback;cameraFullscreen=new FrameLayout(MainActivity.this);cameraFullscreen.setBackgroundColor(Color.BLACK);cameraFullscreen.addView(view,new FrameLayout.LayoutParams(-1,-1));((FrameLayout)getWindow().getDecorView()).addView(cameraFullscreen,new FrameLayout.LayoutParams(-1,-1));getWindow().getInsetsController().hide(WindowInsets.Type.systemBars());getWindow().getInsetsController().setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);}
            @Override public void onHideCustomView(){hideCameraFullscreen();}
            @Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(!trustedPage())return false;if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=callback;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("*/*");String[] accepts=params.getAcceptTypes();if(accepts!=null&&accepts.length==1&&accepts[0].equals(".tar"))intent.setType("application/x-tar");else if(accepts!=null&&accepts.length==1&&accepts[0].contains("/")&&!accepts[0].contains(","))intent.setType(accepts[0]);intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);try{startActivityForResult(intent,PICK_FILE);return true;}catch(Exception e){fileCallback=null;callback.onReceiveValue(null);message("No document picker is available on this device.");return true;}}
            @Override public boolean onJsAlert(WebView view,String url,String value,JsResult result){new AlertDialog.Builder(MainActivity.this).setTitle("VAutomate").setMessage(value).setPositiveButton("OK",(d,w)->result.confirm()).setOnCancelListener(d->result.cancel()).show();return true;}
            @Override public boolean onJsConfirm(WebView view,String url,String value,JsResult result){new AlertDialog.Builder(MainActivity.this).setTitle("VAutomate").setMessage(value).setPositiveButton("Continue",(d,w)->result.confirm()).setNegativeButton("Go back",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}
            @Override public boolean onJsPrompt(WebView view,String url,String value,String initial,JsPromptResult result){EditText input=new EditText(MainActivity.this);input.setText(initial);new AlertDialog.Builder(MainActivity.this).setTitle("VAutomate").setMessage(value).setView(input).setPositiveButton("Save",(d,w)->result.confirm(input.getText().toString())).setNegativeButton("Go back",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}
            @Override public void onPermissionRequest(PermissionRequest request){request.deny();message("This app does not access your phone's camera or microphone. Home camera feeds remain available.");}
            @Override public boolean onCreateWindow(WebView view,boolean dialog,boolean userGesture,Message result){if(!userGesture)return false;WebView popup=new WebView(MainActivity.this);popup.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView child,WebResourceRequest request){String url=request.getUrl().toString();message("External navigation is disabled in Studio Preview.");child.destroy();return true;}});((WebView.WebViewTransport)result.obj).setWebView(popup);result.sendToTarget();return true;}
        });stage.addView(web,0,new FrameLayout.LayoutParams(-1,-1));}
    private void hideCameraFullscreen(){if(cameraFullscreen==null)return;FrameLayout frame=cameraFullscreen;cameraFullscreen=null;if(frame.getParent() instanceof android.view.ViewGroup)((android.view.ViewGroup)frame.getParent()).removeView(frame);frame.removeAllViews();WebChromeClient.CustomViewCallback callback=cameraFullscreenCallback;cameraFullscreenCallback=null;getWindow().getInsetsController().show(WindowInsets.Type.systemBars());if(callback!=null)callback.onCustomViewHidden();}
    private boolean isWebUrl(String value){return value!=null&&(value.startsWith("https://")||value.startsWith("http://"));}
    private boolean trustedPage(){return shell!=null&&shell.getParent()==root&&web!=null&&EndpointPolicy.dashboard(web.getUrl(),origin)&&home!=null&&home.allows(origin);}
    private void openExternal(String url){if(!isWebUrl(url))return;new AlertDialog.Builder(this).setTitle("Open in your browser?").setMessage("This link leaves VAutomate and opens "+Uri.parse(url).getHost()+" in your browser.").setPositiveButton("Open browser",(d,w)->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){message("No browser is available.");}}).setNegativeButton("Stay here",null).show();}

    private void initializePage(){if(!trustedPage()||ready&&port!=null)return;final int ticket=generation;web.evaluateJavascript("Boolean(document.title.includes('VAutomate') && typeof restoreRememberedSession === 'function' && typeof connection === 'function')",value->{if(ticket!=generation||!"true".equals(value)){errorScreen("This version of the dashboard could not initialize. Update VAutomate on the home server and try again.");return;}try{closePort();int epoch=portEpoch;WebMessagePort[] channel=web.createWebMessageChannel();port=channel[0];port.setWebMessageCallback(new WebMessagePort.WebMessageCallback(){@Override public void onMessage(WebMessagePort source,WebMessage message){if(epoch!=portEpoch||!trustedPage())return;dispatchNative(message.getData(),epoch);}});String nonce=bridgeNonce;String script=asset("native-runtime.js").replace("__VA_NATIVE_NONCE__",nonce);web.evaluateJavascript(script,ignored->{if(ticket!=generation||epoch!=portEpoch||!trustedPage())return;web.postWebMessage(new WebMessage("vautomate-native-port-v1|"+nonce,new WebMessagePort[]{channel[1]}),Uri.parse(origin));});}catch(Exception error){errorScreen("The app could not initialize its secure sign-in connection. Reopen VAutomate and try again.");}});}
    private String asset(String name)throws Exception{try(InputStream in=getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);return out.toString("UTF-8");}}
    private void closePort(){portEpoch++;if(port!=null){try{port.close();}catch(Exception ignored){}port=null;}}
    private void reply(String id,Object result,String error,int epoch){main.post(()->{if(port==null||epoch!=portEpoch||!trustedPage())return;try{JSONObject response=new JSONObject().put("id",id);if(error!=null)response.put("error",error);else response.put("result",result==null?JSONObject.NULL:result);port.postMessage(new WebMessage(response.toString()));}catch(Exception ignored){}});}
    private void dispatchNative(String raw,int epoch){if(raw==null||raw.length()>220000)return;String requestId="";try{JSONObject request=new JSONObject(raw);requestId=request.optString("id");if(requestId.length()>80)return;String method=request.optString("method");JSONObject data=request.optJSONObject("data");if(data==null)data=new JSONObject();String id=requestId;String profile=home.id;JSONObject payload=data;
        switch(method){
            case "session.read": vaultJobs.execute(()->{try{String saved=vault.get(profile);JSONObject session=saved==null?null:new JSONObject(saved);if(session!=null&&!home.allows(session.optString("origin"))){reply(id,null,"Sign in again after changing the server addresses.",epoch);return;}reply(id,session,null,epoch);}catch(Exception error){reply(id,null,"Saved sign-in could not be unlocked. Sign in again on this device.",epoch);}});break;
            case "session.save": {String kind=payload.optString("kind"),credential=payload.optString("credential"),client=payload.optString("clientId"),from=payload.optString("origin");if(!kind.equals("account")&&!kind.equals("installer")||credential.length()<10||credential.length()>32000||!home.allows(from)||!home.allows(EndpointPolicy.origin(client)))throw new Exception("Invalid saved session");vaultJobs.execute(()->{try{JSONObject clean=new JSONObject().put("version",1).put("kind",kind).put("credential",credential).put("origin",from).put("clientId",client);vault.put(profile,clean.toString());reply(id,true,null,epoch);}catch(Exception error){reply(id,null,"The sign-in could not be saved securely.",epoch);}});break;}
            case "session.clear": vaultJobs.execute(()->{vault.clear(profile);reply(id,true,null,epoch);});break;
            case "navigation.save": {String route=payload.optString("route");if(route.length()<=500&&route.matches("^#/(overview|rooms|cameras|energy|network|scenes|history|notifications|system|devices|more)(/[^?#]*)?$"))getPreferences(MODE_PRIVATE).edit().putString("last-route:"+profile,route).apply();reply(id,true,null,epoch);break;}
            case "app.ready": ready=true;connecting=false;if(deadline!=null)main.removeCallbacks(deadline);connectionStatus.setText(home.name+" · "+home.label(origin));dismissLoading();if(openNotificationsOnReady){openNotificationsOnReady=false;web.evaluateJavascript("if(typeof go==='function'){go('Notifications');if(typeof refreshHomeNotices==='function')refreshHomeNotices();}",null);}reply(id,true,null,epoch);note("Dashboard ready");break;
            case "app.status": {String status=payload.optString("status");if(status.equals("connected")){ready=true;connectionStatus.setText(home.name+" · "+home.label(origin));}else if(status.equals("offline")){connectionStatus.setText(home.name+" · Reconnecting");main.postDelayed(()->{if(resumed&&!connecting&&epoch==portEpoch)checkCurrentConnection();},3000);}reply(id,true,null,epoch);break;}
            case "notifications.status":try{reply(id,new JSONObject().put("supported",false).put("readOnly",true).put("enabled",false),null,epoch);}catch(Exception ignored){}break;
            case "notifications.configure":reply(id,null,"Phone delivery is not available in this customer candidate.",epoch);break;

            case "app.tailscale.open": {String url=payload.optString("url");if(!EndpointPolicy.tailscaleLink(url))throw new IllegalArgumentException("Unexpected Tailscale link.");openExternal(url);reply(id,true,null,epoch);break;}
            case "app.remote.save": {String remote=EndpointPolicy.tailscaleOrigin(payload.optString("url"));final String selectedProfile=home.id;new AlertDialog.Builder(this).setTitle("Save this home's remote address?").setMessage(home.name+"\n"+remote+"\n\nConnect Tailscale on this phone before using this address while away.").setPositiveButton("Save address",(d,w)->{if(home==null||!home.id.equals(selectedProfile)){reply(id,null,"The selected home changed.",epoch);return;}try{HomeStore.Home updated=new HomeStore.Home(home.id,home.name,home.local,remote);homes.save(updated);home=updated;reply(id,true,null,epoch);}catch(Exception error){reply(id,null,"The remote address could not be saved.",epoch);}}).setNegativeButton("Cancel",(d,w)->reply(id,null,"Remote address was not changed.",epoch)).show();break;}
            case "app.settings":showAppMenu();reply(id,true,null,epoch);break;
            case "app.exit":moveTaskToBack(true);reply(id,true,null,epoch);break;
            case "download.home": {String identity=payload.optString("backup_id");if(!identity.matches("[A-Za-z0-9_-]{1,128}"))throw new Exception();handleDownload(origin+"/api/vautomate_studio/v1/backups/download/"+identity,"attachment; filename=\"VAutomate-backup-"+identity+".tar\"","application/x-tar");reply(id,true,null,epoch);break;}
            case "download.start":startBlobDownload(id,payload,epoch);break;
            case "download.chunk":writeDownloadChunk(id,payload,epoch);break;
            case "download.finish":finishDownload(id,epoch);break;
            case "download.abort":abortDownload();reply(id,true,null,epoch);break;
            default:reply(id,null,"This app action is not supported.",epoch);
        }
    }catch(Exception error){if(!requestId.isEmpty())reply(requestId,null,"This app action could not be completed.",epoch);note("An app action was rejected");}}

    private void checkCurrentConnection(){if(home==null||connecting||!resumed)return;if(arrivalView!=null&&!ready&&deadline!=null)return;if(origin.isEmpty()||web==null||!ready){connect(null,true);return;}String current=origin;int ticket=generation;tasks.execute(()->{ConnectionResolver.Result result=resolver.probe(current);main.post(()->{if(ticket!=generation||!resumed||connecting)return;if(result.success){connectionStatus.setText(home.name+" · "+home.label(origin));return;}withDraftGuard(()->connect(null,true),false);});});}
    private void withDraftGuard(Runnable action,boolean ask){if(pendingDownload!=null||downloadOutput!=null){if(ask)message("Finish the current file export before changing the connection.");return;}if(!trustedPage()){action.run();return;}web.evaluateJavascript("Boolean(typeof platform !== 'undefined' && platform.formDirty && document.querySelector('#modal')?.open)",value->{if("true".equals(value)){if(!ask){connectionStatus.setText(home.name+" · Offline · draft kept");return;}new AlertDialog.Builder(this).setTitle("Leave unsaved changes?").setMessage("Your unsaved dashboard draft will be discarded when the connection changes.").setNegativeButton("Keep editing",null).setPositiveButton("Discard changes",(d,w)->{if(web!=null)web.evaluateJavascript("if(typeof platform!=='undefined')platform.formDirty=false;",ignored->action.run());else action.run();}).show();}else action.run();});}
    private void showAppMenu(){if(home==null){showHomeForm(null);return;}String[] items={"Connection details","Reconnect","Use local connection","Use remote connection","Edit this home","Switch home","Add another home","Forget saved sign-in","Export app diagnostics","About VAutomate","Notifications"};new AlertDialog.Builder(this).setTitle(home.name).setItems(items,(dialog,index)->{switch(index){case 10:message("Phone delivery is not available in this customer candidate.");break;case 0:showConnectionDetails();break;case 1:withDraftGuard(()->connect(null,false),true);break;case 2:if(home.local.isEmpty())message("Add a local address first.");else withDraftGuard(()->connect(home.local,false),true);break;case 3:if(home.remote.isEmpty())message("Add a remote address first.");else withDraftGuard(()->connect(home.remote,false),true);break;case 4:withDraftGuard(()->showHomeForm(home),true);break;case 5:showHomePicker();break;case 6:withDraftGuard(()->showHomeForm(null),true);break;case 7:forgetSignIn();break;case 8:exportDiagnostics();break;case 9:new AlertDialog.Builder(this).setTitle("VAutomate Studio Home · 0.4.0-alpha.13").setMessage("Smart living. Simplified.\n\nCustomer release candidate. Connects through the VAutomate Studio service. The service starts read-only; hardware and HAOS acceptance testing are pending. Personal VAutomate and Studio Preview app data stay separate.\n\nAndroid 12 and newer. No phone camera, microphone or location permissions are requested.").setPositiveButton("Done",null).show();}}).show();}
    private void showConnectionDetails(){new AlertDialog.Builder(this).setTitle("Your home connection").setMessage("At home\n"+(home.local.isEmpty()?"Not configured":home.local)+"\n\nAway\n"+(home.remote.isEmpty()?"Not configured":home.remote)+"\n\nCurrent\n"+(origin.isEmpty()?"Not connected":home.label(origin))+"\n\nRemote access uses the private connection already configured on your phone.").setPositiveButton("Done",null).show();}
    private void showHomePicker(){List<HomeStore.Home> list=homes.all();String[] labels=new String[list.size()+1];for(int i=0;i<list.size();i++)labels[i]=list.get(i).name;labels[list.size()]="Add another home";new AlertDialog.Builder(this).setTitle("Choose your home").setItems(labels,(d,i)->withDraftGuard(()->{if(i==list.size()){showHomeForm(null);return;}HomeStore.Home selected=list.get(i);if(home!=null&&home.id.equals(selected.id)&&ready)return;home=selected;homes.select(selected);origin="";destroyWeb();connect(null,false);},true)).show();}
    private void forgetSignIn(){new AlertDialog.Builder(this).setTitle("Forget this device's sign-in?").setMessage("You will need to sign in again in VAutomate. Your home settings and devices are kept.").setNegativeButton("Keep sign-in",null).setPositiveButton("Forget sign-in",(d,w)->{String profile=home.id;vaultJobs.execute(()->{vault.clear(profile);});if(trustedPage())web.evaluateJavascript("if(window.__VA_NATIVE__)window.__VA_NATIVE__.forget();",ignored->{});message("Saved sign-in removed from this device.");}).show();}
    private void handleBack(){if(cameraFullscreen!=null){hideCameraFullscreen();return;}if(root==null)return;if(trustedPage()&&ready){web.evaluateJavascript("if(window.__VA_NATIVE__)window.__VA_NATIVE__.back();",ignored->{});return;}if(home!=null&&shell!=null&&shell.getParent()!=root){connect(null,false);return;}moveTaskToBack(true);}
    @Override public void onBackPressed(){handleBack();}


    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(intent==null||!intent.hasExtra("notification_home_id"))return;String id=intent.getStringExtra("notification_home_id");for(HomeStore.Home item:homes.all())if(item.id.equals(id)){withDraftGuard(()->{if(home!=null&&home.id.equals(item.id)&&ready&&trustedPage()){web.evaluateJavascript("if(typeof go==='function'){go('Notifications');if(typeof refreshHomeNotices==='function')refreshHomeNotices();}",null);}else{home=item;homes.select(item);openNotificationsOnReady=true;origin="";destroyWeb();connect(null,false);}},true);break;}}
    @Override protected void onResume(){super.onResume();resumed=true;if(wasBackgrounded&&home!=null&&web!=null&&(ready||arrivalView!=null)&&shell!=null&&shell.getParent()==root){showLoading("Welcome home.","Your home. Entirely yours.");if(ready)dismissLoading();}wasBackgrounded=false;if(web!=null){web.onResume();web.resumeTimers();}if(home!=null&&shell!=null&&shell.getParent()==root&&!connecting)main.postDelayed(()->checkCurrentConnection(),500);}
    @Override protected void onPause(){hideCameraFullscreen();wasBackgrounded=true;resumed=false;if(web!=null){web.onPause();web.pauseTimers();}super.onPause();}
    @Override public void onTrimMemory(int level){super.onTrimMemory(level);if(level>=TRIM_MEMORY_RUNNING_LOW)note("Android reported low memory");}
    private void destroyWeb(){hideCameraFullscreen();closePort();if(web!=null){try{web.stopLoading();if(web.getParent()instanceof android.view.ViewGroup)((android.view.ViewGroup)web.getParent()).removeView(web);web.destroy();}catch(Exception ignored){}web=null;}ready=false;}
    @Override protected void onDestroy(){hideCameraFullscreen();generation++;if(recoveryCheck!=null)main.removeCallbacks(recoveryCheck);if(deadline!=null)main.removeCallbacks(deadline);if(fileCallback!=null)fileCallback.onReceiveValue(null);abortDownload();try{connectivity.unregisterNetworkCallback(networkCallback);}catch(Exception ignored){}destroyWeb();resolver.close();tasks.shutdownNow();vaultJobs.shutdown();super.onDestroy();}

    private void exportDiagnostics(){StringBuilder out=new StringBuilder("VAutomate Android 0.4.0-alpha.13\nAndroid API "+Build.VERSION.SDK_INT+"\n");out.append("Connection: ").append(origin.isEmpty()?"Offline":home.label(origin)).append("\n\n");synchronized(events){for(String event:events)out.append(event).append('\n');}exportText=out.toString();Intent create=new Intent(Intent.ACTION_CREATE_DOCUMENT);create.addCategory(Intent.CATEGORY_OPENABLE);create.setType("text/plain");create.putExtra(Intent.EXTRA_TITLE,"vautomate-app-diagnostics.txt");try{startActivityForResult(create,EXPORT_LOG);}catch(Exception error){message("No document picker is available.");}}
    private String safeName(String value){String name=value==null?"download":value.replaceAll("[\\\\/:*?\"<>|\\p{Cntrl}]","_");return name.length()>140?name.substring(0,140):name.isEmpty()?"vautomate-download":name;}
    private void handleDownload(String url,String disposition,String mime){if(!trustedPage())return;if(url.startsWith("blob:")){web.evaluateJavascript("if(window.__VA_NATIVE__)window.__VA_NATIVE__.saveBlob("+JSONObject.quote(url)+",'vautomate-download','application/octet-stream');",null);return;}if(!EndpointPolicy.sameOrigin(url,origin)){message("Only downloads from this home are opened in the app.");return;}if(pendingDownload!=null||downloadOutput!=null){message("Finish the current download first.");return;}String name=URLUtil.guessFileName(url,disposition,mime);pendingDownload=new PendingDownload("",safeName(name),mime==null?"application/octet-stream":mime,url,portEpoch);chooseDownloadDestination();}
    private void startBlobDownload(String id,JSONObject data,int epoch)throws Exception{if(pendingDownload!=null||downloadOutput!=null){reply(id,null,"Finish the current download first.",epoch);return;}long size=data.optLong("size",-1);if(size<0)throw new Exception();downloadExpected=size;pendingDownload=new PendingDownload(id,safeName(data.optString("name","vautomate-download")),data.optString("mime","application/octet-stream"),null,epoch);chooseDownloadDestination();}
    private void chooseDownloadDestination(){Intent create=new Intent(Intent.ACTION_CREATE_DOCUMENT);create.addCategory(Intent.CATEGORY_OPENABLE);create.setType(pendingDownload.mime);create.putExtra(Intent.EXTRA_TITLE,pendingDownload.name);try{startActivityForResult(create,CREATE_DOWNLOAD);}catch(Exception error){PendingDownload pending=pendingDownload;pendingDownload=null;if(!pending.id.isEmpty())reply(pending.id,null,"No document picker is available.",pending.epoch);message("No document picker is available.");}}
    private void writeDownloadChunk(String id,JSONObject data,int epoch)throws Exception{if(downloadOutput==null||epoch!=downloadEpoch||!home.id.equals(downloadProfile))throw new Exception();String encoded=data.optString("chunk");if(encoded.length()>90000)throw new Exception();byte[] chunk=Base64.decode(encoded,Base64.NO_WRAP);if(chunk.length>65536||downloadBytes+chunk.length>downloadExpected)throw new Exception();tasks.execute(()->{try{synchronized(this){if(downloadOutput==null)throw new Exception();downloadOutput.write(chunk);downloadBytes+=chunk.length;}reply(id,true,null,epoch);}catch(Exception error){abortDownload();reply(id,null,"The download could not be written. A partial file may remain in the chosen location.",epoch);}});}
    private void finishDownload(String id,int epoch){tasks.execute(()->{try{synchronized(this){if(downloadOutput==null||epoch!=downloadEpoch||downloadBytes!=downloadExpected)throw new Exception();downloadOutput.flush();downloadOutput.close();downloadOutput=null;}reply(id,true,null,epoch);main.post(()->message("Download saved."));}catch(Exception error){abortDownload();reply(id,null,"The download did not finish. A partial file may remain.",epoch);}});}
    private synchronized void abortDownload(){if(downloadOutput!=null)try{downloadOutput.close();}catch(Exception ignored){}downloadOutput=null;pendingDownload=null;downloadBytes=0;downloadExpected=0;}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK_FILE){if(fileCallback!=null){List<Uri> selected=new ArrayList<>();if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)selected.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)selected.add(data.getData());}fileCallback.onReceiveValue(selected.isEmpty()?null:selected.toArray(new Uri[0]));fileCallback=null;}return;}
        if(request==EXPORT_LOG){String text=exportText;exportText=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null&&text!=null){Uri uri=data.getData();tasks.execute(()->{try(OutputStream output=getContentResolver().openOutputStream(uri)){output.write(text.getBytes(StandardCharsets.UTF_8));main.post(()->message("App diagnostics saved."));}catch(Exception error){main.post(()->message("Diagnostics could not be saved."));}});}return;}
        if(request==CREATE_DOWNLOAD){PendingDownload pending=pendingDownload;pendingDownload=null;if(pending==null)return;if(result!=RESULT_OK||data==null||data.getData()==null){if(!pending.id.isEmpty())reply(pending.id,null,"Download cancelled.",pending.epoch);return;}Uri uri=data.getData();if(pending.url!=null){downloadSignedUrl(pending,uri);return;}if(pending.epoch!=portEpoch||!trustedPage()){message("The page changed before the download started. Try again.");return;}try{downloadOutput=getContentResolver().openOutputStream(uri);downloadBytes=0;downloadEpoch=pending.epoch;downloadProfile=home.id;reply(pending.id,true,null,pending.epoch);}catch(Exception error){reply(pending.id,null,"The selected file could not be opened.",pending.epoch);}}
    }
    private void downloadSignedUrl(PendingDownload pending,Uri uri){String expectedOrigin=origin;String homeCookie=pending.url.startsWith(expectedOrigin+"/api/vautomate_studio/v1/backups/download/")?CookieManager.getInstance().getCookie(pending.url):null;tasks.execute(()->{HttpURLConnection connection=null;try{if(!EndpointPolicy.sameOrigin(pending.url,expectedOrigin))throw new Exception();EndpointPolicy.verifyTransport(expectedOrigin);connection=(HttpURLConnection)new URL(pending.url).openConnection();connection.setConnectTimeout(15000);connection.setReadTimeout(60000);connection.setInstanceFollowRedirects(false);if(homeCookie!=null)connection.setRequestProperty("Cookie",homeCookie);int status=connection.getResponseCode();if(status!=200)throw new Exception();try(InputStream input=connection.getInputStream();OutputStream output=getContentResolver().openOutputStream(uri)){byte[] buffer=new byte[65536];int n;while((n=input.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new Exception();output.write(buffer,0,n);}output.flush();}main.post(()->message("Download saved."));note("Home download saved");}catch(Exception error){note("Home download failed");main.post(()->message("The download could not finish. The signed link may have expired; request a new download. A partial file may remain."));}finally{if(connection!=null)connection.disconnect();}});}
